{
  "name": "roomview-mvp-workspace",
  "private": true,
  "version": "0.1.0",
  "workspaces": [
    "apps/*",
    "packages/*"
  ],
  "scripts": {
    "verify:fixtures": "node ./scripts/verify-fixtures.mjs",
    "check": "npm run verify:fixtures"
  }
}

import type {
  AssetId,
  EntityId,
  ISO8601Timestamp,
  JobId,
  OBB3D,
  Point3D,
  Polygon2D,
  Pose3D,
  RectOnSurface,
  SceneId,
  SnapshotId,
  Vector3D,
} from "./primitives";
import type { MaterialState } from "./primitives";
import type { CameraBookmark, EditableObjectClass, Scene } from "./scene";

export const COMMAND_KIND_VALUES = ["generate_photoreal", "undo_last_change"] as const;
export type CommandKind = (typeof COMMAND_KIND_VALUES)[number];

export const JOB_KIND_VALUES = ["photoreal", "splat"] as const;
export type JobKind = (typeof JOB_KIND_VALUES)[number];

export const JOB_STATUS_VALUES = ["queued", "processing", "ready", "failed"] as const;
export type JobStatus = (typeof JOB_STATUS_VALUES)[number];

export const HANDOFF_GRANT_STATUS_VALUES = ["issued", "redeemed", "expired", "revoked"] as const;
export type HandoffGrantStatus = (typeof HANDOFF_GRANT_STATUS_VALUES)[number];

export const VIDEO_UPLOAD_TOKEN_STATUS_VALUES = ["issued", "used", "expired", "revoked"] as const;
export type VideoUploadTokenStatus = (typeof VIDEO_UPLOAD_TOKEN_STATUS_VALUES)[number];

export const REASON_CODE_VALUES = [
  "AUTH_REQUIRED",
  "SCENE_ACCESS_DENIED",
  "HANDOFF_EXPIRED",
  "HANDOFF_ALREADY_USED",
  "AMBIGUOUS_TARGET",
  "TARGET_NOT_FOUND",
  "VERSION_CONFLICT",
  "APPLY_TOKEN_INVALID",
  "APPLY_TOKEN_EXPIRED",
  "IDEMPOTENCY_CONFLICT",
  "ENTITY_LOCKED",
  "OBJECT_OVERLAP",
  "OUT_OF_BOUNDS",
  "OPENING_BLOCKED",
  "CLEARANCE_VIOLATION",
  "ANCHOR_VIOLATION",
  "UNSUPPORTED_CLASS",
  "ASSET_NOT_AVAILABLE",
  "PARENT_MOVE_VIOLATION",
  "UNDO_NOT_AVAILABLE",
  "SCENE_DELETED",
  "PHOTOREAL_PROVIDER_ERROR",
  "INVALID_CAPTURE",
  "ROOM_TYPE_NOT_SUPPORTED",
  "MULTI_ROOM_NOT_SUPPORTED",
  "VIDEO_UPLOAD_TOKEN_INVALID",
  "VIDEO_UPLOAD_TOKEN_EXPIRED",
  "VIDEO_UPLOAD_TOKEN_ALREADY_USED",
] as const;
export type ReasonCode = (typeof REASON_CODE_VALUES)[number];

export interface RoomPlanCaptureRequest {
  request_id: string;
  client_capture_id: string;
  roomplan_payload: RoomPlanPayload;
  capture_metadata: CaptureMetadata;
  supplementary_detections: SupplementaryDetection[] | null;
}

export interface RoomPlanPayload {
  schema_version: string;
  room_type: "bedroom" | string;
  coordinate_frame: {
    origin: Point3D;
    x_axis: Vector3D;
    y_axis: Vector3D;
    z_axis: Vector3D;
    north_source: "true_north" | "scan_forward";
  };
  dimensions: {
    width_m: number;
    length_m: number;
    ceiling_height_m: number;
  };
  surfaces: RoomPlanSurfaceSeed[];
  openings: RoomPlanOpeningSeed[];
  objects: RoomPlanObjectSeed[];
  fixed_elements?: RoomPlanFixedElementSeed[] | null;
  room_count?: number | null;
}

export interface CaptureMetadata {
  room_type_hint: "bedroom";
  units: "m";
  device_model: string;
  captured_at: ISO8601Timestamp;
  video_expected: boolean;
}

export interface SupplementaryDetection {
  detection_id: string;
  label: string;
  obb: OBB3D;
  confidence: number;
}

export interface RoomPlanCaptureResponse {
  scene_id: SceneId;
  scene_version: number;
  scene_snapshot_id: SnapshotId;
  handoff_url: string;
  qr_payload: string;
  expires_at: ISO8601Timestamp;
  video_upload_token: string | null;
}

export interface HandoffRedeemRequest {
  handoff_token: string;
}

export interface HandoffRedeemResponse {
  scene_id: SceneId;
  session_id: string;
  redeemed_at: ISO8601Timestamp;
  expires_at: ISO8601Timestamp;
}

export interface OperationPlanRequest {
  request_id: string;
  idempotency_key: string;
  scene_id: SceneId;
  expected_scene_version: number;
  selection_context: {
    selected_entity_ids: EntityId[];
  };
  user_prompt: string;
}

export interface OperationPlanPreview {
  request_id: string;
  preview_id: string;
  based_on_scene_version: number;
  ops: SceneEditOperation[];
  explanation: string;
  canonical_plan_hash: string;
  apply_token: string;
  apply_token_expires_at: ISO8601Timestamp;
  idempotency_key: string;
}

export interface CommandRequest {
  request_id: string;
  command_kind: CommandKind;
  endpoint: string;
  explanation: string;
  idempotency_key: string;
}

export interface ApplyPlanRequest {
  preview_id: string;
  apply_token: string;
  canonical_plan_hash: string;
  expected_scene_version: number;
  idempotency_key: string;
}

export interface ClarificationRequest {
  response_kind: "clarification_request";
  request_id: string;
  prompt: string;
  options: string[];
}

export interface OperationPlanPreviewResponse {
  response_kind: "operation_plan_preview";
  preview: OperationPlanPreview;
}

export interface CommandRequestResponse {
  response_kind: "command_request";
  command: CommandRequest;
}

export interface RejectionResponse {
  response_kind: "rejection";
  request_id: string;
  reason_code: ReasonCode;
  message: string;
}

export type PlannerResponse =
  | ClarificationRequest
  | OperationPlanPreviewResponse
  | CommandRequestResponse
  | RejectionResponse;

export interface MoveObjectOperation {
  op: "move_object";
  object_id: EntityId;
  target_position: Point3D;
  target_named_wall_ref_id?: EntityId | null;
  target_window_opening_id?: EntityId | null;
  include_children?: boolean;
}

export interface RotateObjectOperation {
  op: "rotate_object";
  object_id: EntityId;
  yaw_degrees: number;
  include_children?: boolean;
}

export interface ReplaceObjectOperation {
  op: "replace_object";
  object_id: EntityId;
  desired_class: EditableObjectClass;
  style_tags: string[];
  asset_id?: AssetId | null;
}

export interface PlacementRelation {
  relation: "named_wall" | "window" | "surface_point";
  target_entity_id: EntityId;
  offset_meters?: number;
}

export interface AddObjectOperation {
  op: "add_object";
  object_id: EntityId;
  object_class: EditableObjectClass;
  style_tags: string[];
  placement_relation?: PlacementRelation | null;
  pose?: Pose3D | null;
}

export interface RemoveObjectOperation {
  op: "remove_object";
  object_id: EntityId;
}

export interface LockEntityOperation {
  op: "lock_entity";
  entity_id: EntityId;
  entity_type: "object" | "surface";
}

export interface UnlockEntityOperation {
  op: "unlock_entity";
  entity_id: EntityId;
  entity_type: "object" | "surface";
}

export interface RepaintSurfaceOperation {
  op: "repaint_surface";
  surface_id: EntityId;
  color: string;
  finish?: string | null;
}

export interface SwapFlooringOperation {
  op: "swap_flooring";
  surface_id: EntityId;
  material_state: MaterialState;
}

export type SceneEditOperation =
  | MoveObjectOperation
  | RotateObjectOperation
  | ReplaceObjectOperation
  | AddObjectOperation
  | RemoveObjectOperation
  | LockEntityOperation
  | UnlockEntityOperation
  | RepaintSurfaceOperation
  | SwapFlooringOperation;

export interface SceneReadResponse {
  scene: Scene;
}

export interface SceneApplyResponse {
  scene: Scene;
  applied_snapshot_id: SnapshotId;
  applied_scene_version: number;
  validation_summary: {
    hard_violations: Array<Record<string, unknown>>;
    soft_scores: Record<string, number>;
  };
}

export interface GeneratePhotorealRequest {
  scene_snapshot_id: SnapshotId;
  bookmark_id?: string | null;
  camera_pose?: Pose3D | null;
  fov?: number | null;
  prompt_modifiers: string[];
  idempotency_key: string;
}

export interface UndoLastChangeRequest {
  expected_scene_version: number;
  idempotency_key: string;
}

export interface VideoUploadRequest {
  video_upload_token: string;
  content_type: string;
}

export interface VideoUploadResponse {
  job_id: JobId;
}

export interface DeleteSceneRequest {
  idempotency_key: string;
}

export interface JobRecord {
  job_id: JobId;
  scene_id: SceneId;
  job_kind: JobKind;
  status: JobStatus;
  source_scene_version: number | null;
  scene_snapshot_id: SnapshotId | null;
  created_at: ISO8601Timestamp;
  updated_at: ISO8601Timestamp;
  output_asset_id: AssetId | null;
  error_code: ReasonCode | null;
}

export interface HandoffGrantRecord {
  grant_id: string;
  scene_id: SceneId;
  token_hash: string;
  qr_payload: string;
  status: HandoffGrantStatus;
  expires_at: ISO8601Timestamp;
  redeemed_at: ISO8601Timestamp | null;
  redeemed_session_id?: string | null;
}

export interface VideoUploadTokenRecord {
  token_id: string;
  scene_id: SceneId;
  token_hash: string;
  status: VideoUploadTokenStatus;
  expires_at: ISO8601Timestamp;
  used_at: ISO8601Timestamp | null;
  created_at: ISO8601Timestamp;
}

export interface IdempotencyRecord {
  scope: string;
  idempotency_key: string;
  request_hash: string;
  response_status_code: number;
  response_body: Record<string, unknown>;
  scene_id: SceneId | null;
  created_at: ISO8601Timestamp;
  updated_at: ISO8601Timestamp;
}

export interface RoomPlanSurfaceSeed {
  id: string;
  category: "wall" | "floor" | "ceiling";
  polygon: Polygon2D;
  frame: {
    origin: Point3D;
    u_axis: Vector3D;
    v_axis: Vector3D;
    normal: Vector3D;
  } | null;
}

export interface RoomPlanOpeningSeed {
  id: string;
  category: "door" | "window" | "closet_door";
  host_surface_id: string;
  rect: RectOnSurface;
}

export interface RoomPlanObjectSeed {
  id: string;
  category: string;
  pose: Pose3D;
  obb: OBB3D;
  attributes: string[];
}

export interface RoomPlanFixedElementSeed {
  id: string;
  category: string;
  pose: Pose3D;
  obb: OBB3D;
  attributes?: string[];
  host_surface_id?: string | null;
}

export interface FixtureDescriptor {
  fixture_id: string;
  request_path: string;
  scene_path: string;
  notes: string;
}

export interface FixtureManifest {
  fixtures: FixtureDescriptor[];
}

export interface BookmarkSeed {
  bookmark: CameraBookmark;
}

import type {
  AssetId,
  BookmarkId,
  EntityId,
  ISO8601Timestamp,
  JobId,
  OBB3D,
  Point2D,
  Polygon2D,
  Pose3D,
  Provenance,
  RectOnSurface,
  RoomCoordinateFrame,
  SceneId,
  SnapshotId,
  SurfaceFrame,
  Units,
} from "./primitives";
import type { MaterialState } from "./primitives";

export const MUTATION_KIND_VALUES = ["initial_ingest", "edit_plan", "undo_restore"] as const;
export type MutationKind = (typeof MUTATION_KIND_VALUES)[number];

export const ROOM_TYPE_VALUES = ["bedroom"] as const;
export type RoomType = (typeof ROOM_TYPE_VALUES)[number];

export const SURFACE_TYPE_VALUES = ["wall", "floor", "ceiling"] as const;
export type SurfaceType = (typeof SURFACE_TYPE_VALUES)[number];

export const OPENING_TYPE_VALUES = ["door", "window", "closet_door"] as const;
export type OpeningType = (typeof OPENING_TYPE_VALUES)[number];

export const OBJECT_MOBILITY_VALUES = ["movable", "anchored", "fixed"] as const;
export type ObjectMobility = (typeof OBJECT_MOBILITY_VALUES)[number];

export const CHILD_MOVEMENT_POLICY_VALUES = ["move_with_parent", "independent"] as const;
export type ChildMovementPolicy = (typeof CHILD_MOVEMENT_POLICY_VALUES)[number];

export const HOST_RELATION_TYPE_VALUES = [
  "flush_to_wall",
  "mounted_to_wall",
  "embedded_in_wall",
  "ceiling_mounted",
] as const;
export type HostRelationType = (typeof HOST_RELATION_TYPE_VALUES)[number];

export const SUPPORT_KIND_VALUES = ["floor", "wall", "ceiling", "object"] as const;
export type SupportKind = (typeof SUPPORT_KIND_VALUES)[number];

export const FOCAL_ELEMENT_TYPE_VALUES = ["object", "opening", "fixed_element", "surface"] as const;
export type FocalElementType = (typeof FOCAL_ELEMENT_TYPE_VALUES)[number];

export const FOCAL_ELEMENT_ROLE_VALUES = ["primary", "secondary"] as const;
export type FocalElementRole = (typeof FOCAL_ELEMENT_ROLE_VALUES)[number];

export const CONSTRAINT_KIND_VALUES = [
  "opening_preserved",
  "walkway_clearance",
  "no_overlap_in_bounds",
  "anchor_integrity",
  "class_specific_clearance",
  "desk_near_window",
  "sofa_faces_focal_element",
  "primary_path_not_serpentine",
] as const;
export type ConstraintKind = (typeof CONSTRAINT_KIND_VALUES)[number];

export const CONSTRAINT_SEVERITY_VALUES = ["hard", "soft"] as const;
export type ConstraintSeverity = (typeof CONSTRAINT_SEVERITY_VALUES)[number];

export const ASSET_KIND_VALUES = ["gltf", "proxy_gltf"] as const;
export type AssetKind = (typeof ASSET_KIND_VALUES)[number];

export const SPLAT_STATUS_VALUES = ["queued", "processing", "ready", "failed"] as const;
export type SplatStatus = (typeof SPLAT_STATUS_VALUES)[number];

export const EDITABLE_OBJECT_CLASS_VALUES = [
  "bed",
  "nightstand",
  "desk",
  "chair",
  "table",
  "dresser",
  "bookshelf",
  "sofa",
  "rug",
  "lamp",
  "television",
  "storage",
] as const;
export type EditableObjectClass = (typeof EDITABLE_OBJECT_CLASS_VALUES)[number];

export type ObjectClass = EditableObjectClass | "generic_obstacle";

export interface SceneHead {
  scene_id: SceneId;
  source: "scanned";
  units: Units;
  current_snapshot_id: SnapshotId;
  current_scene_version: number;
  undo_base_snapshot_id: SnapshotId | null;
  updated_at: ISO8601Timestamp;
}

export interface SceneSnapshot {
  snapshot_id: SnapshotId;
  scene_id: SceneId;
  scene_version: number;
  based_on_snapshot_id: SnapshotId | null;
  mutation_kind: MutationKind;
  state: SceneState;
  editing_asset_refs: AssetRef[];
  created_at: ISO8601Timestamp;
}

export interface Scene {
  head: SceneHead;
  snapshot: SceneSnapshot;
  derived_state_cache: DerivedState | null;
  bookmarks: CameraBookmark[];
  photoreal_gallery: PhotorealEntry[];
  splat: SplatAssetRecord | null;
}

export interface SceneState {
  style_tags: string[];
  room: Room;
}

export interface Room {
  room_id: EntityId;
  room_type: RoomType;
  coordinate_frame: RoomCoordinateFrame;
  shell: Shell;
  objects: SceneObject[];
  constraints: ConstraintSpec[];
  focal_elements: FocalElementRef[];
  section_hints: string[];
}

export interface Shell {
  floor_polygon: Polygon2D;
  ceiling_height: number;
  surfaces: Surface[];
  named_wall_refs: NamedWallRef[];
  openings: Opening[];
  fixed_elements: FixedElement[];
}

export interface Surface {
  surface_id: EntityId;
  type: SurfaceType;
  geometry_ref: string;
  boundary: Polygon2D;
  surface_frame: SurfaceFrame | null;
  named_wall_ref_id: EntityId | null;
  material_state: MaterialState;
  user_locked: boolean;
  provenance: Provenance;
}

export interface Opening {
  opening_id: EntityId;
  host_surface_id: EntityId;
  type: OpeningType;
  rect: RectOnSurface;
  swing_zone: Polygon2D | null;
  keepout_zone: Polygon2D | null;
  connects_to_room_id: EntityId | null;
  provenance: Provenance;
}

export interface SceneObject {
  object_id: EntityId;
  class: ObjectClass;
  attributes: string[];
  parent_id: EntityId | null;
  child_movement_policy: ChildMovementPolicy;
  pose: Pose3D;
  obb: OBB3D;
  mobility: ObjectMobility;
  host: HostRelation | null;
  support: SupportRelation;
  asset_ref: AssetId | null;
  style_tags: string[];
  material_state: MaterialState | null;
  user_locked: boolean;
  provenance: Provenance;
}

export interface FixedElement {
  fixed_element_id: EntityId;
  class: string;
  pose: Pose3D;
  obb: OBB3D;
  host: HostRelation | null;
  support: SupportRelation;
  keepout_zone: Polygon2D | null;
  provenance: Provenance;
}

export interface AssetRef {
  asset_id: AssetId;
  kind: AssetKind;
  uri: string;
  bound_to: EntityId;
}

export interface SplatAssetRecord {
  scene_id: SceneId;
  source_scene_version: number;
  status: SplatStatus;
  asset_id: AssetId | null;
  uri: string | null;
  job_id?: JobId | null;
  updated_at: ISO8601Timestamp;
}

export interface NamedWallRef {
  wall_ref_id: EntityId;
  name: string;
  surface_ids: EntityId[];
  azimuth_degrees: number;
  inward_normal_xy: Point2D;
}

export interface HostRelation {
  relation_type: HostRelationType;
  host_surface_id: EntityId;
  anchor_rect: RectOnSurface | null;
}

export interface SupportRelation {
  support_kind: SupportKind;
  support_entity_id: EntityId;
  contact_patch: Polygon2D | RectOnSurface | null;
}

export interface FocalElementRef {
  entity_id: EntityId;
  entity_type: FocalElementType;
  role: FocalElementRole;
  reason: string;
}

export interface ConstraintSpec {
  constraint_id: EntityId;
  kind: ConstraintKind;
  severity: ConstraintSeverity;
  target_entity_ids: EntityId[];
  params: Record<string, unknown>;
  reason_code_on_fail: string | null;
}

export interface CameraBookmark {
  bookmark_id: BookmarkId;
  name: string;
  camera_pose: Pose3D;
  fov: number;
  created_at: ISO8601Timestamp;
  updated_at: ISO8601Timestamp;
}

export interface PhotorealEntry {
  entry_id: EntityId;
  asset_id: AssetId;
  scene_version: number;
  scene_snapshot_id: SnapshotId;
  bookmark_id: BookmarkId | null;
  camera_pose: Pose3D;
  fov: number;
  prompt_modifiers: string[];
  provider_metadata?: Record<string, unknown>;
  created_at: ISO8601Timestamp;
}

export interface DerivedState {
  zones: Array<Record<string, unknown>>;
  clearance_paths: Array<Record<string, unknown>>;
  soft_scores: Record<string, number>;
  hard_violations: Array<Record<string, unknown>>;
  selection_context_summary: string;
}

export interface OperationSummary {
  request_id: string;
  ops: Array<Record<string, unknown>>;
  timestamp: ISO8601Timestamp;
  user_message: string;
}

export type Object = SceneObject;

export type ISO8601Timestamp = string;
export type EntityId = string;
export type SnapshotId = string;
export type SceneId = string;
export type JobId = string;
export type BookmarkId = string;
export type AssetId = string;

export const SCENE_SOURCE_VALUES = ["scanned"] as const;
export type SceneSource = (typeof SCENE_SOURCE_VALUES)[number];

export const UNITS_VALUES = ["m"] as const;
export type Units = (typeof UNITS_VALUES)[number];

export interface Point2D {
  x: number;
  y: number;
}

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface Vector3D {
  x: number;
  y: number;
  z: number;
}

export interface Polygon2D {
  vertices: Point2D[];
}

export interface RectOnSurface {
  min_u: number;
  min_v: number;
  width: number;
  height: number;
}

export interface Pose3D {
  position: Point3D;
  yaw_degrees: number;
}

export interface OBB3D {
  center: Point3D;
  size_x: number;
  size_y: number;
  size_z: number;
  yaw_degrees: number;
}

export const NORTH_SOURCE_VALUES = ["true_north", "scan_forward"] as const;
export type NorthSource = (typeof NORTH_SOURCE_VALUES)[number];

export interface RoomCoordinateFrame {
  origin: Point3D;
  x_axis: Vector3D;
  y_axis: Vector3D;
  z_axis: Vector3D;
  north_source: NorthSource;
}

export interface SurfaceFrame {
  origin: Point3D;
  u_axis: Vector3D;
  v_axis: Vector3D;
  normal: Vector3D;
}

export interface MaterialState {
  category: string;
  color: string;
  finish: string | null;
  pattern: string | null;
  reference_asset_id: AssetId | null;
}

export const PROVENANCE_SOURCE_KIND_VALUES = [
  "measured",
  "inferred",
  "generated",
  "user_authored",
] as const;
export type ProvenanceSourceKind = (typeof PROVENANCE_SOURCE_KIND_VALUES)[number];

export interface Provenance {
  source_kind: ProvenanceSourceKind;
  confidence: number;
  source_ref: string | null;
  updated_at: ISO8601Timestamp;
}

export * from "./primitives";
export * from "./scene";
export * from "./api";

import { createHash, randomBytes } from "node:crypto";

import type {
  AssetRef,
  CameraBookmark,
  ConstraintSpec,
  DerivedState,
  EditableObjectClass,
  FixedElement,
  HandoffGrantRecord,
  HandoffRedeemRequest,
  HandoffRedeemResponse,
  JobRecord,
  MaterialState,
  NamedWallRef,
  ObjectClass,
  Opening,
  Point2D,
  Point3D,
  Polygon2D,
  Pose3D,
  ReasonCode,
  RectOnSurface,
  Room,
  RoomPlanCaptureRequest,
  RoomPlanCaptureResponse,
  RoomPlanFixedElementSeed,
  RoomPlanObjectSeed,
  RoomPlanOpeningSeed,
  RoomPlanPayload,
  RoomPlanSurfaceSeed,
  Scene,
  SceneObject,
  SupportRelation,
  Surface,
  SurfaceFrame,
  SplatAssetRecord,
  SupplementaryDetection,
  VideoUploadTokenRecord,
  VideoUploadRequest,
  VideoUploadResponse,
} from "@roomview/contracts";

const EDITABLE_OBJECT_CLASSES = new Set<EditableObjectClass>([
  "bed",
  "nightstand",
  "desk",
  "chair",
  "table",
  "dresser",
  "bookshelf",
  "sofa",
  "rug",
  "lamp",
  "television",
  "storage",
]);

const WALL_NAME_TO_AZIMUTH: Record<string, number> = {
  "north wall": 0,
  "east wall": 90,
  "south wall": 180,
  "west wall": 270,
};

const DEFAULT_HANDOFF_TTL_MS = 1000 * 60 * 15;
const DEFAULT_VIDEO_UPLOAD_TTL_MS = 1000 * 60 * 10;
const DEFAULT_SESSION_TTL_MS = 1000 * 60 * 60 * 8;
const DEFAULT_CLEARANCE_WIDTH_M = 0.76;

interface AssetTemplate {
  asset_id: string;
  kind: "gltf" | "proxy_gltf";
  uri: string;
  style_tags: string[];
  material_state: MaterialState | null;
  preferred_size_xy: { x: number; y: number };
  max_relative_error: number;
}

const DEFAULT_FLOOR_MATERIAL: MaterialState = {
  category: "flooring",
  color: "oak",
  finish: "matte",
  pattern: "plank",
  reference_asset_id: "asset-floor-oak-01",
};

const DEFAULT_WALL_MATERIAL: MaterialState = {
  category: "paint",
  color: "warm_white",
  finish: "eggshell",
  pattern: null,
  reference_asset_id: null,
};

const DEFAULT_CEILING_MATERIAL: MaterialState = {
  category: "paint",
  color: "soft_white",
  finish: "flat",
  pattern: null,
  reference_asset_id: null,
};

const ASSET_LIBRARY: Record<EditableObjectClass, AssetTemplate[]> = {
  bed: [
    {
