import type {
  CameraBookmark,
  DerivedState,
  HandoffGrantRecord,
  ISO8601Timestamp,
  PhotorealEntry,
  Scene,
  SceneHead,
  SceneId,
  SceneSnapshot,
  SplatAssetRecord,
  VideoUploadTokenRecord,
} from "@roomview/contracts";

import type { IngestedCaptureArtifacts } from "./roomplan-ingest";

export interface PersistedSceneHeadRecord extends SceneHead {
  created_at: ISO8601Timestamp;
  deleted_at: ISO8601Timestamp | null;
}

export interface PersistedDerivedStateCacheRecord {
  snapshot_id: string;
  scene_id: SceneId;
  scene_version: number;
  derived_state: DerivedState;
  created_at: ISO8601Timestamp;
  updated_at: ISO8601Timestamp;
}

export interface PersistedCameraBookmarkRecord extends CameraBookmark {
  scene_id: SceneId;
}

export interface PersistedPhotorealEntryRecord extends PhotorealEntry {
  scene_id: SceneId;
}

export interface PersistedInitialSceneRecords {
  scene_head: PersistedSceneHeadRecord;
  scene_snapshot: SceneSnapshot;
  derived_state_cache: PersistedDerivedStateCacheRecord | null;
  camera_bookmarks: PersistedCameraBookmarkRecord[];
  photoreal_entries: PersistedPhotorealEntryRecord[];
  splat_asset_record: SplatAssetRecord | null;
  handoff_grant: HandoffGrantRecord;
  video_upload_token_record: VideoUploadTokenRecord | null;
}

export function decomposeIngestedCaptureForStorage(
  artifacts: IngestedCaptureArtifacts
): PersistedInitialSceneRecords {
  const scene = structuredClone(artifacts.scene);
  const createdAt = scene.snapshot.created_at;

  return {
    scene_head: {
      ...scene.head,
      created_at: createdAt,
      deleted_at: null,
    },
    scene_snapshot: structuredClone(scene.snapshot),
    derived_state_cache: scene.derived_state_cache
      ? {
          snapshot_id: scene.snapshot.snapshot_id,
          scene_id: scene.head.scene_id,
          scene_version: scene.head.current_scene_version,
          derived_state: structuredClone(scene.derived_state_cache),
          created_at: createdAt,
          updated_at: scene.head.updated_at,
        }
      : null,
    camera_bookmarks: scene.bookmarks.map((bookmark) => ({
      ...structuredClone(bookmark),
      scene_id: scene.head.scene_id,
    })),
    photoreal_entries: scene.photoreal_gallery.map((entry) => ({
      ...structuredClone(entry),
      scene_id: scene.head.scene_id,
    })),
    splat_asset_record: scene.splat ? structuredClone(scene.splat) : null,
    handoff_grant: structuredClone(artifacts.handoff_grant),
    video_upload_token_record: artifacts.video_upload_token_record
      ? structuredClone(artifacts.video_upload_token_record)
      : null,
  };
}

export function hydrateSceneFromStoredRecords(records: PersistedInitialSceneRecords): Scene {
  const head = structuredClone(records.scene_head);
  const { created_at: _createdAt, deleted_at: _deletedAt, ...sceneHead } = head;

  return {
    head: sceneHead,
    snapshot: structuredClone(records.scene_snapshot),
    derived_state_cache: records.derived_state_cache
      ? structuredClone(records.derived_state_cache.derived_state)
      : null,
    bookmarks: records.camera_bookmarks.map(({ scene_id: _sceneId, ...bookmark }) => structuredClone(bookmark)),
    photoreal_gallery: records.photoreal_entries.map(({ scene_id: _sceneId, ...entry }) => structuredClone(entry)),
    splat: records.splat_asset_record ? structuredClone(records.splat_asset_record) : null,
  };
}

import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import assert from "node:assert/strict";

import {
  buildInitialSceneFromRoomPlanCapture,
  decomposeIngestedCaptureForStorage,
  hydrateSceneFromStoredRecords,
  ingestRoomPlanCaptureRequest,
} from "../apps/api/src/index.ts";

interface FixtureDescriptor {
  fixture_id: string;
  request_path: string;
  scene_path: string;
}

interface FixtureManifest {
  fixtures: FixtureDescriptor[];
}

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");

function readJson<T>(relativePath: string): T {
  return JSON.parse(readFileSync(resolve(repoRoot, relativePath), "utf8")) as T;
}

function normalizeQrPayload(qrPayload: string): Record<string, unknown> {
  const parsed = JSON.parse(qrPayload) as Record<string, unknown>;
  return {
    ...parsed,
    handoff_token: parsed.handoff_token ? "<opaque>" : parsed.handoff_token,
  };
}

function normalizeHandoffUrl(handoffUrl: string): string {
  const parsed = new URL(handoffUrl);
  const segments = parsed.pathname.split("/").filter(Boolean);
  if (segments.length > 0) {
    segments[segments.length - 1] = "<opaque>";
  }
  parsed.pathname = `/${segments.join("/")}`;
  return parsed.toString();
}

function normalizePersistedRecords(value: unknown): unknown {
  if (value === null || typeof value !== "object") {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(normalizePersistedRecords);
  }

  const record = value as Record<string, unknown>;
  const normalized: Record<string, unknown> = {};
  for (const [key, current] of Object.entries(record)) {
    if (key === "qr_payload" && typeof current === "string") {
      normalized[key] = normalizeQrPayload(current);
      continue;
    }
    if (key === "handoff_url" && typeof current === "string") {
      normalized[key] = normalizeHandoffUrl(current);
      continue;
    }
    if (key === "grant_id" || key === "token_id" || key === "token_hash") {
      normalized[key] = "<opaque>";
      continue;
    }
    if (key === "video_upload_token") {
      normalized[key] = current === null ? null : "<opaque>";
      continue;
    }
    normalized[key] = normalizePersistedRecords(current);
  }
  return normalized;
}

const manifest = readJson<FixtureManifest>("fixtures/manifest.json");

for (const fixture of manifest.fixtures) {
  const request = readJson(fixture.request_path);
  const expectedScene = readJson(fixture.scene_path);
  const replay = buildInitialSceneFromRoomPlanCapture(request).scene;

  assert.deepStrictEqual(
    replay,
    expectedScene,
    `${fixture.fixture_id}: replayed scene does not match ${fixture.scene_path}`
  );

  const ingestedA = ingestRoomPlanCaptureRequest(request);
  const ingestedB = ingestRoomPlanCaptureRequest(request);
  const persistedA = decomposeIngestedCaptureForStorage(ingestedA);
  const persistedB = decomposeIngestedCaptureForStorage(ingestedB);

  assert.deepStrictEqual(
    hydrateSceneFromStoredRecords(persistedA),
    ingestedA.scene,
    `${fixture.fixture_id}: stored records do not hydrate back to the canonical scene`
  );

  assert.deepStrictEqual(
    normalizePersistedRecords(persistedA),
    normalizePersistedRecords(persistedB),
    `${fixture.fixture_id}: persisted records are not deterministic across replays`
  );

  assert.deepStrictEqual(
    normalizePersistedRecords(ingestedA.response),
    normalizePersistedRecords(ingestedB.response),
    `${fixture.fixture_id}: capture responses are not deterministic across replays`
  );
}

console.log(`Verified deterministic replay parity for ${manifest.fixtures.length} fixture scene(s)`);

}

